"""Sortie ZF4, batch 5: Parseval for the shifted Gauss sums and the norm of
the Gauss sum (LConvexity gaussSum_mul_conj / norm_gaussSum_sq, LargeSieve
norm_sq_gaussSum_primitive, LGrowth norm_gaussSum_le)."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf4lib import *
from zf2lib import REPF
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

RN = R('N'); F0 = FZO('N'); L = LZ('N'); C = COND('N', 'X'); T = GS('N', 'X'); DN = DB('N')
def XL(a, x='X'): return EV(x, 'N', a)
def CJ(e): return '( * ` %s )' % e
def fin(w, ante): return w.s([w.s([], 'fzofi', '%s e. Fin' % F0)], 'a1i', '( %s -> %s e. Fin )' % (ante, F0))
def elz(w, ante, mem, v): return w.s([mem, w.inst('elfzoelz')], 'syl', '( %s -> %s e. ZZ )' % (ante, v))
def xcl(w, E4, ante, xst, zst, v, x='X'):
    g, z, d, l = E4
    return w.s([g, z, d, l, xst, zst], 'dchrzrhcl', '( %s -> %s e. CC )' % (ante, XL(v, x)))
def rcl(w, ante, nst, kst, k):
    return w.s([nst, kst, w.inst('root1expcl')], 'syl2anc', '( %s -> %s e. CC )' % (ante, RP(k)))
def rcl0(w, ante, nst):
    cl = w.s([nst, w.inst('root1cl')], 'syl', '( %s -> ( %s e. CC /\\ %s =/= 0 ) )' % (ante, RN, RN))
    return cl

# the Parseval summands
def XX(b, c, x='X'): return '( %s x. %s )' % (XL(b, x), CJ(XL(c, x)))
def TT(b, c, k): return '( %s x. %s )' % (XX(b, c), RP('( %s x. ( %s - %s ) )' % (k, b, c)))

# ---- dchr2sumz: set.mm dchr2sum over the integer representatives
A0 = '( N e. NN /\\ X e. %s /\\ Y e. %s )' % (DN, DN)
BN = BZ('N'); RF = REPF('N')
w = W('dchr2sumz', 'Orthogonality of Dirichlet characters (set.mm dchr2sum) summed over the integer representatives ( 0 ..^ N ).')
n = w.s([], 'simp1', '( %s -> N e. NN )' % A0); x = w.s([], 'simp2', '( %s -> X e. %s )' % (A0, DN)); y = w.s([], 'simp3', '( %s -> Y e. %s )' % (A0, DN))
g, z, d, l = dchyp(w); bb = w.s([], 'eqid', '%s = %s' % (BN, BN))
BODY = '( ( X ` b ) x. ( * ` ( Y ` b ) ) )'; IF = 'if ( X = Y , ( phi ` N ) , 0 )'
d2s = w.s([g, z, d, bb, x, y], 'dchr2sum', '( %s -> sum_ b e. %s %s = %s )' % (A0, BN, BODY, IF))
fn = fin(w, A0)
bij = w.s([n, w.inst('dchrindlem0')], 'syl', '( %s -> %s : %s -1-1-onto-> %s )' % (A0, RF, F0, BN))
Aa = '( %s /\\ a e. %s )' % (A0, F0)
val = w.s([w.s([], 'simpr', '( %s -> a e. %s )' % (Aa, F0))], 'fvresd', '( %s -> ( %s ` a ) = ( %s ` a ) )' % (Aa, RF, L))
Ab = '( %s /\\ b e. %s )' % (A0, BN)
xf = w.s([g, z, d, bb, w.s([x], 'adantr', '( %s -> X e. %s )' % (Ab, DN))], 'dchrf', '( %s -> X : %s --> CC )' % (Ab, BN))
yf = w.s([g, z, d, bb, w.s([y], 'adantr', '( %s -> Y e. %s )' % (Ab, DN))], 'dchrf', '( %s -> Y : %s --> CC )' % (Ab, BN))
bm = w.s([], 'simpr', '( %s -> b e. %s )' % (Ab, BN))
xb = w.s([xf, bm], 'ffvelcdmd', '( %s -> ( X ` b ) e. CC )' % Ab); yb = w.s([yf, bm], 'ffvelcdmd', '( %s -> ( Y ` b ) e. CC )' % Ab)
bcl = w.s([xb, w.s([yb], 'cjcld', '( %s -> ( * ` ( Y ` b ) ) e. CC )' % Ab)], 'mulcld', '( %s -> %s e. CC )' % (Ab, BODY))
re, D = fsumf1o(w, A0, 'b', BN, BODY, 'a', F0, RF, '( %s ` a )' % L, fn, bij, val, bcl)
assert D == '( %s x. %s )' % (XL('a'), CJ(XL('a', 'Y'))), D
w.qed([re, d2s], 'eqtr3d', '( %s -> sum_ a e. %s %s = %s )' % (A0, F0, D, IF)); run(w)

# ---- dchrgsparlem1: the shifted Gauss sum times its conjugate as a double sum
A1 = '( %s /\\ A e. ZZ )' % HC
GRA = GR('X', 'N', 'A'); TA = TERMR('X', 'N', 'a', 'A')
w = W('dchrgsparlem1', 'Lemma for dchrgspar: the shifted Gauss sum times its conjugate is the double sum of X ( b ) conj X ( c ) times the root of unity at A ( b - c ) (Lean hexpand in LConvexity gaussSum_mul_conj).')
hc = w.s([], 'simpl', '( %s -> %s )' % (A1, HC)); n = w.s([hc], 'simpld', '( %s -> N e. NN )' % A1); x = w.s([hc], 'simprd', '( %s -> X e. %s )' % (A1, DN)); a = w.s([], 'simpr', '( %s -> A e. ZZ )' % A1)
E4 = dchyp(w)
def termcl(ante, v, nst, xst, ast, vz):
    return w.s([xcl(w, E4, ante, xst, vz, v), rcl(w, ante, nst, w.s([ast, vz], 'zmulcld', '( %s -> ( A x. %s ) e. ZZ )' % (ante, v)), '( A x. %s )' % v)], 'mulcld', '( %s -> %s e. CC )' % (ante, TERMR('X', 'N', v, 'A')))
Aa = '( %s /\\ a e. %s )' % (A1, F0)
az = elz(w, Aa, w.s([], 'simpr', '( %s -> a e. %s )' % (Aa, F0)), 'a')
tcla = termcl(Aa, 'a', w.s([n], 'adantr', '( %s -> N e. NN )' % Aa), w.s([x], 'adantr', '( %s -> X e. %s )' % (Aa, DN)), w.s([a], 'adantr', '( %s -> A e. ZZ )' % Aa), az)
fn = fin(w, A1)
cj = w.s([fn, tcla], 'fsumcj', '( %s -> %s = sum_ a e. %s %s )' % (A1, CJ(GRA), F0, CJ(TA)))
cb1, TB = cbvsum(w, F0, TA, 'a', 'b'); cb2, TC = cbvsum(w, F0, CJ(TA), 'a', 'c')
assert TB == TERMR('X', 'N', 'b', 'A') and TC == CJ(TERMR('X', 'N', 'c', 'A')), (TB, TC)
SB = 'sum_ b e. %s %s' % (F0, TB); SC = 'sum_ c e. %s %s' % (F0, TC)
lhs = w.s([w.s([cb1], 'a1i', '( %s -> %s = %s )' % (A1, GRA, SB)), w.s([cj, w.s([cb2], 'a1i', '( %s -> sum_ a e. %s %s = %s )' % (A1, F0, CJ(TA), SC))], 'eqtrd', '( %s -> %s = %s )' % (A1, CJ(GRA), SC))], 'oveq12d', '( %s -> ( %s x. %s ) = ( %s x. %s ) )' % (A1, GRA, CJ(GRA), SB, SC))
Ab = '( %s /\\ b e. %s )' % (A1, F0); Ac = '( %s /\\ c e. %s )' % (A1, F0)
bz = elz(w, Ab, w.s([], 'simpr', '( %s -> b e. %s )' % (Ab, F0)), 'b'); cz = elz(w, Ac, w.s([], 'simpr', '( %s -> c e. %s )' % (Ac, F0)), 'c')
tclb = termcl(Ab, 'b', w.s([n], 'adantr', '( %s -> N e. NN )' % Ab), w.s([x], 'adantr', '( %s -> X e. %s )' % (Ab, DN)), w.s([a], 'adantr', '( %s -> A e. ZZ )' % Ab), bz)
tclc = w.s([termcl(Ac, 'c', w.s([n], 'adantr', '( %s -> N e. NN )' % Ac), w.s([x], 'adantr', '( %s -> X e. %s )' % (Ac, DN)), w.s([a], 'adantr', '( %s -> A e. ZZ )' % Ac), cz)], 'cjcld', '( %s -> %s e. CC )' % (Ac, TC))
PROD = '( %s x. %s )' % (TB, TC)
m2 = w.s([fn, fn, tclb, tclc], 'fsum2mul', '( %s -> sum_ b e. %s sum_ c e. %s %s = ( %s x. %s ) )' % (A1, F0, F0, PROD, SB, SC))
# the summand under ( ( A1 /\ b e. F0 ) /\ c e. F0 )
Abc = '( %s /\\ c e. %s )' % (Ab, F0)
n2 = w.s([n], 'ad2antrr', '( %s -> N e. NN )' % Abc); x2 = w.s([x], 'ad2antrr', '( %s -> X e. %s )' % (Abc, DN)); a2 = w.s([a], 'ad2antrr', '( %s -> A e. ZZ )' % Abc)
bz2 = w.s([bz], 'adantr', '( %s -> b e. ZZ )' % Abc); cz2 = elz(w, Abc, w.s([], 'simpr', '( %s -> c e. %s )' % (Abc, F0)), 'c')
XB = XL('b'); XC = XL('c'); AB = '( A x. b )'; AC = '( A x. c )'
xbc = xcl(w, E4, Abc, x2, bz2, 'b'); xcc = xcl(w, E4, Abc, x2, cz2, 'c'); cxc = w.s([xcc], 'cjcld', '( %s -> %s e. CC )' % (Abc, CJ(XC)))
abz = w.s([a2, bz2], 'zmulcld', '( %s -> %s e. ZZ )' % (Abc, AB)); acz = w.s([a2, cz2], 'zmulcld', '( %s -> %s e. ZZ )' % (Abc, AC))
rb = rcl(w, Abc, n2, abz, AB); rc = rcl(w, Abc, n2, acz, AC); nacz = w.s([acz], 'znegcld', '( %s -> -u %s e. ZZ )' % (Abc, AC)); rnc = rcl(w, Abc, n2, nacz, '-u %s' % AC)
e1 = w.s([xcc, rc], 'cjmuld', '( %s -> %s = ( %s x. %s ) )' % (Abc, TC, CJ(XC), CJ(RP(AC))))
e2 = w.s([w.s([n2, acz, w.inst('root1cjz')], 'syl2anc', '( %s -> %s = %s )' % (Abc, CJ(RP(AC)), RP('-u %s' % AC)))], 'oveq2d', '( %s -> ( %s x. %s ) = ( %s x. %s ) )' % (Abc, CJ(XC), CJ(RP(AC)), CJ(XC), RP('-u %s' % AC)))
e3 = w.s([w.s([e1, e2], 'eqtrd', '( %s -> %s = ( %s x. %s ) )' % (Abc, TC, CJ(XC), RP('-u %s' % AC)))], 'oveq2d', '( %s -> %s = ( %s x. ( %s x. %s ) ) )' % (Abc, PROD, TB, CJ(XC), RP('-u %s' % AC)))
e4 = w.s([xbc, rb, cxc, rnc], 'mul4d', '( %s -> ( %s x. ( %s x. %s ) ) = ( %s x. ( %s x. %s ) ) )' % (Abc, TB, CJ(XC), RP('-u %s' % AC), XX('b', 'c'), RP(AB), RP('-u %s' % AC)))
ea = w.s([w.s([rcl0(w, Abc, n2), w.s([abz, nacz], 'jca', '( %s -> ( %s e. ZZ /\\ -u %s e. ZZ ) )' % (Abc, AB, AC)), w.inst('expaddz')], 'syl2anc', '( %s -> %s = ( %s x. %s ) )' % (Abc, RP('( %s + -u %s )' % (AB, AC)), RP(AB), RP('-u %s' % AC)))], 'eqcomd', '( %s -> ( %s x. %s ) = %s )' % (Abc, RP(AB), RP('-u %s' % AC), RP('( %s + -u %s )' % (AB, AC))))
acn = w.s([a2], 'zcnd', '( %s -> A e. CC )' % Abc); bcn = w.s([bz2], 'zcnd', '( %s -> b e. CC )' % Abc); ccn = w.s([cz2], 'zcnd', '( %s -> c e. CC )' % Abc)
ex1 = w.s([w.s([abz], 'zcnd', '( %s -> %s e. CC )' % (Abc, AB)), w.s([acz], 'zcnd', '( %s -> %s e. CC )' % (Abc, AC))], 'negsubd', '( %s -> ( %s + -u %s ) = ( %s - %s ) )' % (Abc, AB, AC, AB, AC))
ex2 = w.s([w.s([acn, bcn, ccn], 'subdid', '( %s -> ( A x. ( b - c ) ) = ( %s - %s ) )' % (Abc, AB, AC))], 'eqcomd', '( %s -> ( %s - %s ) = ( A x. ( b - c ) ) )' % (Abc, AB, AC))
ex = w.s([w.s([ex1, ex2], 'eqtrd', '( %s -> ( %s + -u %s ) = ( A x. ( b - c ) ) )' % (Abc, AB, AC))], 'oveq2d', '( %s -> %s = %s )' % (Abc, RP('( %s + -u %s )' % (AB, AC)), RP('( A x. ( b - c ) )')))
e5 = w.s([w.s([ea, ex], 'eqtrd', '( %s -> ( %s x. %s ) = %s )' % (Abc, RP(AB), RP('-u %s' % AC), RP('( A x. ( b - c ) )')))], 'oveq2d', '( %s -> ( %s x. ( %s x. %s ) ) = %s )' % (Abc, XX('b', 'c'), RP(AB), RP('-u %s' % AC), TT('b', 'c', 'A')))
summand = w.s([w.s([e3, e4], 'eqtrd', '( %s -> %s = ( %s x. ( %s x. %s ) ) )' % (Abc, PROD, XX('b', 'c'), RP(AB), RP('-u %s' % AC))), e5], 'eqtrd', '( %s -> %s = %s )' % (Abc, PROD, TT('b', 'c', 'A')))
s2 = w.s([w.s([summand], 'sumeq2dv', '( %s -> sum_ c e. %s %s = sum_ c e. %s %s )' % (Ab, F0, PROD, F0, TT('b', 'c', 'A')))], 'sumeq2dv', '( %s -> sum_ b e. %s sum_ c e. %s %s = sum_ b e. %s sum_ c e. %s %s )' % (A1, F0, F0, PROD, F0, F0, TT('b', 'c', 'A')))
w.qed([w.s([lhs, w.s([m2], 'eqcomd', '( %s -> ( %s x. %s ) = sum_ b e. %s sum_ c e. %s %s )' % (A1, SB, SC, F0, F0, PROD))], 'eqtrd', '( %s -> ( %s x. %s ) = sum_ b e. %s sum_ c e. %s %s )' % (A1, GRA, CJ(GRA), F0, F0, PROD)), s2], 'eqtrd', '( %s -> ( %s x. %s ) = sum_ b e. %s sum_ c e. %s %s )' % (A1, GRA, CJ(GRA), F0, F0, TT('b', 'c', 'A'))); run(w)

# ---- dchrgsparlem2: the inner orthogonality sum as a delta
A2 = '( %s /\\ ( b e. %s /\\ c e. %s ) )' % (HC, F0, F0)
SK = 'sum_ k e. %s %s' % (F0, RP('( k x. ( b - c ) )'))
w = W('dchrgsparlem2', 'Lemma for dchrgspar: the orthogonality sum over k of the root of unity at k ( b - c ) is N when b = c and 0 otherwise, for residues b, c.')
n = w.s([w.s([], 'simpl', '( %s -> %s )' % (A2, HC))], 'simpld', '( %s -> N e. NN )' % A2)
b = w.s([w.s([], 'simpr', '( %s -> ( b e. %s /\\ c e. %s ) )' % (A2, F0, F0))], 'simpld', '( %s -> b e. %s )' % (A2, F0)); c = w.s([w.s([], 'simpr', '( %s -> ( b e. %s /\\ c e. %s ) )' % (A2, F0, F0))], 'simprd', '( %s -> c e. %s )' % (A2, F0))
wz = w.s([elz(w, A2, b, 'b'), elz(w, A2, c, 'c')], 'zsubcld', '( %s -> ( b - c ) e. ZZ )' % A2)
rs = w.s([n, wz, w.inst('root1sum')], 'syl2anc', '( %s -> %s = if ( N || ( b - c ) , N , 0 ) )' % (A2, SK))
ce = w.s([n, b, c, w.inst('fzocongeq0')], 'syl3anc', '( %s -> ( N || ( b - c ) <-> b = c ) )' % A2)
w.qed([rs, w.s([ce], 'ifbid', '( %s -> if ( N || ( b - c ) , N , 0 ) = if ( b = c , N , 0 ) )' % A2)], 'eqtrd', '( %s -> %s = if ( b = c , N , 0 ) )' % (A2, SK)); run(w)

# ---- dchrgspar: Parseval for the shifted Gauss sums
GRK = GR('X', 'N', 'k'); PK = '( %s x. %s )' % (GRK, CJ(GRK)); TTK = TT('b', 'c', 'k')
def S(v, body): return 'sum_ %s e. %s %s' % (v, F0, body)
w = W('dchrgspar', 'Parseval for the shifted Gauss sums: the sum over the shifts k of the squared modulus of the Gauss sum shifted by k is N phi ( N ) (Lean hway2 in LConvexity gaussSum_mul_conj, hkey in LargeSieve norm_sq_gaussSum_primitive).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HC); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HC, DN))
E4 = dchyp(w)
def ttcl(ante, nst, xst, kz, bz, cz):
    xx = w.s([xcl(w, E4, ante, xst, bz, 'b'), w.s([xcl(w, E4, ante, xst, cz, 'c')], 'cjcld', '( %s -> %s e. CC )' % (ante, CJ(XL('c'))))], 'mulcld', '( %s -> %s e. CC )' % (ante, XX('b', 'c')))
    return xx, w.s([xx, rcl(w, ante, nst, w.s([kz, w.s([bz, cz], 'zsubcld', '( %s -> ( b - c ) e. ZZ )' % ante)], 'zmulcld', '( %s -> ( k x. ( b - c ) ) e. ZZ )' % ante), '( k x. ( b - c ) )')], 'mulcld', '( %s -> %s e. CC )' % (ante, TTK))
Ak = '( %s /\\ k e. %s )' % (HC, F0)
kz = elz(w, Ak, w.s([], 'simpr', '( %s -> k e. %s )' % (Ak, F0)), 'k')
l1 = w.s([w.s([], 'simpl', '( %s -> %s )' % (Ak, HC)), kz, w.inst('dchrgsparlem1')], 'syl2anc', '( %s -> %s = %s )' % (Ak, PK, S('b', S('c', TTK))))
s1 = w.s([l1], 'sumeq2dv', '( %s -> %s = %s )' % (HC, S('k', PK), S('k', S('b', S('c', TTK)))))
# swap k and b
Akb = '( %s /\\ ( k e. %s /\\ b e. %s ) )' % (HC, F0, F0); Akbc = '( %s /\\ c e. %s )' % (Akb, F0)
kb = w.s([], 'simpr', '( %s -> ( k e. %s /\\ b e. %s ) )' % (Akb, F0, F0))
kz1 = w.s([elz(w, Akb, w.s([kb], 'simpld', '( %s -> k e. %s )' % (Akb, F0)), 'k')], 'adantr', '( %s -> k e. ZZ )' % Akbc)
bz1 = w.s([elz(w, Akb, w.s([kb], 'simprd', '( %s -> b e. %s )' % (Akb, F0)), 'b')], 'adantr', '( %s -> b e. ZZ )' % Akbc)
cz1 = elz(w, Akbc, w.s([], 'simpr', '( %s -> c e. %s )' % (Akbc, F0)), 'c')
_, tcl1 = ttcl(Akbc, w.s([n], 'ad2antrr', '( %s -> N e. NN )' % Akbc), w.s([x], 'ad2antrr', '( %s -> X e. %s )' % (Akbc, DN)), kz1, bz1, cz1)
scl1 = w.s([fin(w, Akb), tcl1], 'fsumcl', '( %s -> %s e. CC )' % (Akb, S('c', TTK)))
fn = fin(w, HC)
com1 = w.s([fn, fn, scl1], 'fsumcom', '( %s -> %s = %s )' % (HC, S('k', S('b', S('c', TTK))), S('b', S('k', S('c', TTK)))))
# under ( HC /\ b e. F0 ): swap k and c, collapse
Ab = '( %s /\\ b e. %s )' % (HC, F0); Abkc = '( %s /\\ ( k e. %s /\\ c e. %s ) )' % (Ab, F0, F0); Abc = '( %s /\\ c e. %s )' % (Ab, F0); Abck = '( %s /\\ k e. %s )' % (Abc, F0)
nb = w.s([n], 'adantr', '( %s -> N e. NN )' % Ab); xb = w.s([x], 'adantr', '( %s -> X e. %s )' % (Ab, DN))
bz = elz(w, Ab, w.s([], 'simpr', '( %s -> b e. %s )' % (Ab, F0)), 'b')
kc = w.s([], 'simpr', '( %s -> ( k e. %s /\\ c e. %s ) )' % (Abkc, F0, F0))
_, tcl2 = ttcl(Abkc, w.s([nb], 'adantr', '( %s -> N e. NN )' % Abkc), w.s([xb], 'adantr', '( %s -> X e. %s )' % (Abkc, DN)), elz(w, Abkc, w.s([kc], 'simpld', '( %s -> k e. %s )' % (Abkc, F0)), 'k'), w.s([bz], 'adantr', '( %s -> b e. ZZ )' % Abkc), elz(w, Abkc, w.s([kc], 'simprd', '( %s -> c e. %s )' % (Abkc, F0)), 'c'))
fnb = fin(w, Ab)
com2 = w.s([fnb, fnb, tcl2], 'fsumcom', '( %s -> %s = %s )' % (Ab, S('k', S('c', TTK)), S('c', S('k', TTK))))
# under Abc: sum_k TTK = XX x. if ( b = c , N , 0 )
nbc = w.s([nb], 'adantr', '( %s -> N e. NN )' % Abc); xbc = w.s([xb], 'adantr', '( %s -> X e. %s )' % (Abc, DN))
bz2 = w.s([bz], 'adantr', '( %s -> b e. ZZ )' % Abc); cz2 = elz(w, Abc, w.s([], 'simpr', '( %s -> c e. %s )' % (Abc, F0)), 'c')
xx2 = w.s([xcl(w, E4, Abc, xbc, bz2, 'b'), w.s([xcl(w, E4, Abc, xbc, cz2, 'c')], 'cjcld', '( %s -> %s e. CC )' % (Abc, CJ(XL('c'))))], 'mulcld', '( %s -> %s e. CC )' % (Abc, XX('b', 'c')))
kz3 = elz(w, Abck, w.s([], 'simpr', '( %s -> k e. %s )' % (Abck, F0)), 'k')
rk = rcl(w, Abck, w.s([nbc], 'adantr', '( %s -> N e. NN )' % Abck), w.s([kz3, w.s([w.s([bz2], 'adantr', '( %s -> b e. ZZ )' % Abck), w.s([cz2], 'adantr', '( %s -> c e. ZZ )' % Abck)], 'zsubcld', '( %s -> ( b - c ) e. ZZ )' % Abck)], 'zmulcld', '( %s -> ( k x. ( b - c ) ) e. ZZ )' % Abck), '( k x. ( b - c ) )')
