l2 = w.s([w.s([], 'simpll', '( %s -> %s )' % (Abc, HC)), w.s([w.s([], 'simplr', '( %s -> b e. %s )' % (Abc, F0)), w.s([], 'simpr', '( %s -> c e. %s )' % (Abc, F0))], 'jca', '( %s -> ( b e. %s /\\ c e. %s ) )' % (Abc, F0, F0)), w.inst('dchrgsparlem2')], 'syl2anc', '( %s -> %s = %s )' % (Abc, SK, IFB))
