ss = w.s([bm], 'snssd', '( %s -> { b } C_ %s )' % (Ab, F0))
ncn = w.s([nb], 'nncnd', '( %s -> N e. CC )' % Ab)
dcl = w.s([xx2, w.s([w.s([nbc], 'nncnd', '( %s -> N e. CC )' % Abc), w.s([], '0cnd', '( %s -> 0 e. CC )' % Abc)], 'ifcld', '( %s -> %s e. CC )' % (Abc, IFB))], 'mulcld', '( %s -> %s e. CC )' % (Abc, DC))
Asn = '( %s /\\ c e. { b } )' % Ab
h2 = w.s([w.s([w.s([ss], 'adantr', '( %s -> { b } C_ %s )' % (Asn, F0)), w.s([], 'simpr', '( %s -> c e. { b } )' % Asn)], 'sseldd', '( %s -> c e. %s )' % (Asn, F0)), dcl], 'syldan', '( %s -> %s e. CC )' % (Asn, DC))
Adf = '( %s /\\ c e. ( %s \\ { b } ) )' % (Ab, F0)
cdf = w.s([], 'simpr', '( %s -> c e. ( %s \\ { b } ) )' % (Adf, F0))
ne = w.s([w.s([cdf, w.inst('eldifsni')], 'syl', '( %s -> c =/= b )' % Adf)], 'necomd', '( %s -> b =/= c )' % Adf)
if0 = w.s([w.s([ne], 'neneqd', '( %s -> -. b = c )' % Adf)], 'iffalsed', '( %s -> %s = 0 )' % (Adf, IFB))
xx3 = w.s([w.s([cdf], 'eldifad', '( %s -> c e. %s )' % (Adf, F0)), xx2], 'syldan', '( %s -> %s e. CC )' % (Adf, XX('b', 'c')))
h3 = w.s([w.s([if0], 'oveq2d', '( %s -> %s = ( %s x. 0 ) )' % (Adf, DC, XX('b', 'c'))), w.s([xx3], 'mul01d', '( %s -> ( %s x. 0 ) = 0 )' % (Adf, XX('b', 'c')))], 'eqtrd', '( %s -> %s = 0 )' % (Adf, DC))
