xxb = w.s([xcl(w, E4, Ab, xb, bz, 'b'), w.s([xcl(w, E4, Ab, xb, bz, 'b')], 'cjcld', '( %s -> %s e. CC )' % (Ab, CJ(XL('b'))))], 'mulcld', '( %s -> %s e. CC )' % (Ab, XXB))
dbcl = w.s([xxb, ncn], 'mulcld', '( %s -> %s e. CC )' % (Ab, DB_))
