assert DCB == '( %s x. if ( b = b , N , 0 ) )' % XXB, DCB
ift = w.s([w.s([w.s([], 'eqid', 'b = b')], 'iftruei', 'if ( b = b , N , 0 ) = N')], 'oveq2i', '%s = %s' % (DCB, DB_))
