ssn = w.s([bm, dbcl, w.s([sub], 'sumsn', '( ( b e. %s /\\ %s e. CC ) -> sum_ c e. { b } %s = %s )' % (F0, DB_, DC, DB_))], 'syl2anc', '( %s -> sum_ c e. { b } %s = %s )' % (Ab, DC, DB_))
delta = w.s([fss, ssn], 'eqtr3d', '( %s -> %s = %s )' % (Ab, S('c', DC), DB_))
inner = w.s([w.s([com2, s2], 'eqtrd', '( %s -> %s = %s )' % (Ab, S('k', S('c', TTK)), S('c', DC))), delta], 'eqtrd', '( %s -> %s = %s )' % (Ab, S('k', S('c', TTK)), DB_))
