w.qed([chain, w.s([phc, w.s([n], 'nncnd', '( %s -> N e. CC )' % HC)], 'mulcomd', '( %s -> ( ( phi ` N ) x. N ) = ( N x. ( phi ` N ) ) )' % HC)], 'eqtrd', '( %s -> %s = ( N x. ( phi ` N ) ) )' % (HC, S('k', PK))); run(w)

# ---- dchrgsabslem: the Parseval sum for a primitive character by the shift identity
HP = '( %s /\\ %s = N )' % (HC, C)
