w = W('dchrgsabslem', 'Lemma for dchrgsabs: for a primitive character the Parseval sum is the squared modulus of the Gauss sum times phi ( N ) (Lean hway1 in LConvexity gaussSum_mul_conj, hsum in LargeSieve norm_sq_gaussSum_primitive).')
hc = w.s([], 'simpl', '( %s -> %s )' % (HP, HC)); cn = w.s([], 'simpr', '( %s -> %s = N )' % (HP, C))
n = w.s([hc], 'simpld', '( %s -> N e. NN )' % HP); x = w.s([hc], 'simprd', '( %s -> X e. %s )' % (HP, DN))
Ak = '( %s /\\ k e. %s )' % (HP, F0)
kz = elz(w, Ak, w.s([], 'simpr', '( %s -> k e. %s )' % (Ak, F0)), 'k')
sp = w.s([w.s([hc], 'adantr', '( %s -> %s )' % (Ak, HC)), w.s([cn], 'adantr', '( %s -> %s = N )' % (Ak, C)), kz, w.inst('dchrgsshiftp')], 'syl3anc', '( %s -> %s = ( %s x. %s ) )' % (Ak, G('X', 'N', 'k'), IXK, T))
ef = w.s([w.s([n], 'adantr', '( %s -> N e. NN )' % Ak), kz, w.inst('dchrgsefsum')], 'syl2anc', '( %s -> %s = %s )' % (Ak, G('X', 'N', 'k'), GRK))
gr = w.s([ef, sp], 'eqtr3d', '( %s -> %s = ( %s x. %s ) )' % (Ak, GRK, IXK, T))
g = w.s([], 'eqid', '( DChr ` N ) = ( DChr ` N )'); d = w.s([], 'eqid', '%s = %s' % (DN, DN)); i = w.s([], 'eqid', '%s = %s' % (INV('N'), INV('N')))
grp = w.s([w.s([n, w.s([g], 'dchrabl', '( N e. NN -> ( DChr ` N ) e. Abel )')], 'syl', '( %s -> ( DChr ` N ) e. Abel )' % HP)], 'ablgrpd', '( %s -> ( DChr ` N ) e. Grp )' % HP)
ix = w.s([grp, x, w.s([d, i], 'grpinvcl', '( ( ( DChr ` N ) e. Grp /\\ X e. %s ) -> %s e. %s )' % (DN, IX, DN))], 'syl2anc', '( %s -> %s e. %s )' % (HP, IX, DN))
E4 = dchyp(w)
ixk = xcl(w, E4, Ak, w.s([ix], 'adantr', '( %s -> %s e. %s )' % (Ak, IX, DN)), kz, 'k', IX)
tc = w.s([hc, w.inst('dchrgscl')], 'syl', '( %s -> %s e. CC )' % (HP, T)); tck = w.s([tc], 'adantr', '( %s -> %s e. CC )' % (Ak, T))
cj = w.s([w.s([gr], 'fveq2d', '( %s -> %s = ( * ` ( %s x. %s ) ) )' % (Ak, CJ(GRK), IXK, T)), w.s([ixk, tck], 'cjmuld', '( %s -> ( * ` ( %s x. %s ) ) = ( %s x. %s ) )' % (Ak, IXK, T, CJ(IXK), CJ(T)))], 'eqtrd', '( %s -> %s = ( %s x. %s ) )' % (Ak, CJ(GRK), CJ(IXK), CJ(T)))
QK = '( %s x. %s )' % (IXK, CJ(IXK))
pr = w.s([w.s([gr, cj], 'oveq12d', '( %s -> %s = ( ( %s x. %s ) x. ( %s x. %s ) ) )' % (Ak, PK, IXK, T, CJ(IXK), CJ(T))), w.s([ixk, tck, w.s([ixk], 'cjcld', '( %s -> %s e. CC )' % (Ak, CJ(IXK))), w.s([tck], 'cjcld', '( %s -> %s e. CC )' % (Ak, CJ(T)))], 'mul4d', '( %s -> ( ( %s x. %s ) x. ( %s x. %s ) ) = ( %s x. %s ) )' % (Ak, IXK, T, CJ(IXK), CJ(T), QK, TCT))], 'eqtrd', '( %s -> %s = ( %s x. %s ) )' % (Ak, PK, QK, TCT))
s1 = w.s([pr], 'sumeq2dv', '( %s -> %s = %s )' % (HP, S('k', PK), S('k', '( %s x. %s )' % (QK, TCT))))
qcl = w.s([ixk, w.s([ixk], 'cjcld', '( %s -> %s e. CC )' % (Ak, CJ(IXK)))], 'mulcld', '( %s -> %s e. CC )' % (Ak, QK))
tct = w.s([tc, w.s([tc], 'cjcld', '( %s -> %s e. CC )' % (HP, CJ(T)))], 'mulcld', '( %s -> %s e. CC )' % (HP, TCT))
m1 = w.s([fin(w, HP), tct, qcl], 'fsummulc1', '( %s -> ( %s x. %s ) = %s )' % (HP, S('k', QK), TCT, S('k', '( %s x. %s )' % (QK, TCT))))
d2 = w.s([n, ix, ix, w.inst('dchr2sumz')], 'syl3anc', '( %s -> %s = if ( %s = %s , %s , 0 ) )' % (HP, S('k', QK), IX, IX, PHI))
d3 = w.s([d2, w.s([w.s([], 'eqidd', '( %s -> %s = %s )' % (HP, IX, IX))], 'iftrued', '( %s -> if ( %s = %s , %s , 0 ) = %s )' % (HP, IX, IX, PHI, PHI))], 'eqtrd', '( %s -> %s = %s )' % (HP, S('k', QK), PHI))
w.qed([w.s([s1, w.s([m1], 'eqcomd', '( %s -> %s = ( %s x. %s ) )' % (HP, S('k', '( %s x. %s )' % (QK, TCT)), S('k', QK), TCT))], 'eqtrd', '( %s -> %s = ( %s x. %s ) )' % (HP, S('k', PK), S('k', QK), TCT)), w.s([d3], 'oveq1d', '( %s -> ( %s x. %s ) = ( %s x. %s ) )' % (HP, S('k', QK), TCT, PHI, TCT))], 'eqtrd', '( %s -> %s = ( %s x. %s ) )' % (HP, S('k', PK), PHI, TCT)); run(w)

# ---- dchrgsabs: the squared modulus of a primitive Gauss sum is N
w = W('dchrgsabs', 'The squared modulus of the Gauss sum of a primitive character mod N is N (Lean LConvexity norm_gaussSum_sq, LargeSieve norm_sq_gaussSum_primitive; Mathlib gaussSum_mul_gaussSum_eq_card is the prime-modulus case).')
hc = w.s([], 'simpl', '( %s -> %s )' % (HP, HC)); n = w.s([hc], 'simpld', '( %s -> N e. NN )' % HP)
p = w.s([hc, w.inst('dchrgspar')], 'syl', '( %s -> %s = ( N x. %s ) )' % (HP, S('k', PK), PHI))
l = w.s([], 'dchrgsabslem', '( %s -> %s = ( %s x. %s ) )' % (HP, S('k', PK), PHI, TCT))
tc = w.s([hc, w.inst('dchrgscl')], 'syl', '( %s -> %s e. CC )' % (HP, T))
tct = w.s([tc, w.s([tc], 'cjcld', '( %s -> %s e. CC )' % (HP, CJ(T)))], 'mulcld', '( %s -> %s e. CC )' % (HP, TCT))
ph = w.s([n, w.inst('phicl')], 'syl', '( %s -> %s e. NN )' % (HP, PHI))
eq = w.s([l, p], 'eqtr3d', '( %s -> ( %s x. %s ) = ( N x. %s ) )' % (HP, PHI, TCT, PHI))
can = w.s([tct, w.s([n], 'nncnd', '( %s -> N e. CC )' % HP), w.s([ph], 'nncnd', '( %s -> %s e. CC )' % (HP, PHI)), w.s([ph], 'nnne0d', '( %s -> %s =/= 0 )' % (HP, PHI))], 'mulcand', '( %s -> ( ( %s x. %s ) = ( %s x. N ) <-> %s = N ) )' % (HP, PHI, TCT, PHI, TCT))
eq2 = w.s([eq, w.s([w.s([n], 'nncnd', '( %s -> N e. CC )' % HP), w.s([ph], 'nncnd', '( %s -> %s e. CC )' % (HP, PHI))], 'mulcomd', '( %s -> ( N x. %s ) = ( %s x. N ) )' % (HP, PHI, PHI))], 'eqtrd', '( %s -> ( %s x. %s ) = ( %s x. N ) )' % (HP, PHI, TCT, PHI))
w.qed([w.s([tc, w.inst('absvalsq')], 'syl', '( %s -> ( ( abs ` %s ) ^ 2 ) = %s )' % (HP, T, TCT)), w.s([eq2, can], 'mpbid', '( %s -> %s = N )' % (HP, TCT))], 'eqtrd', '( %s -> ( ( abs ` %s ) ^ 2 ) = N )' % (HP, T)); run(w)

