fc = w.s([fn, w.s([], '1cnd', '( %s -> 1 e. CC )' % HC), w.inst('fsumconst')], 'syl2anc', '( %s -> %s = ( ( # ` %s ) x. 1 ) )' % (HC, S('a', '1'), F0))
h = w.s([w.s([w.s([n], 'nnnn0d', '( %s -> N e. NN0 )' % HC), w.inst('hashfzo0')], 'syl', '( %s -> ( # ` %s ) = N )' % (HC, F0))], 'oveq1d', '( %s -> ( ( # ` %s ) x. 1 ) = ( N x. 1 ) )' % (HC, F0))
